#!/usr/bin/env python3
"""Generate Phase50 decision/report and append an evidence entry to research_log."""
from __future__ import annotations
import hashlib
import json
import os
import subprocess
from datetime import datetime, timezone
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'outputs/iclr27_phase50'; DOC=ROOT/'docs/iclr27_phase50'

def sha(path):
 h=hashlib.sha256()
 with open(path,'rb') as f:
  for b in iter(lambda:f.read(1<<20),b''): h.update(b)
 return h.hexdigest()

def read(p): return json.loads((ROOT/p).read_text())

def live_phase50_workers():
 """Inspect /proc directly and exclude this finalizer itself."""
 out=[]
 for ent in Path('/proc').glob('[0-9]*'):
  try:
   pid=int(ent.name)
   if pid==os.getpid(): continue
   raw=(ent/'cmdline').read_bytes().replace(b'\0',b' ').decode(errors='ignore')
   if 'scripts/iclr27_phase50/' in raw and ('train_end_to_end.py' in raw or 'run_four_fold_supervisor.sh' in raw):
    out.append(f'{pid} {raw.strip()}')
  except (FileNotFoundError,PermissionError,ValueError):
   continue
 return '\n'.join(sorted(out))

def main():
 retrieval=read('outputs/iclr27_phase50/metrics/phase50_retrieval.json')
 inv=read('outputs/iclr27_phase50/audit/supervision_inventory.json')
 resources=read('outputs/iclr27_phase50/audit/resource_preflight.json')
 p16=retrieval['aggregate']['16']; folds=retrieval['folds']
 ck={str(f):{'path':str(OUT/f'checkpoints/e2e_formal_f{f}_best.pt'),'sha256':sha(OUT/f'checkpoints/e2e_formal_f{f}_best.pt')} for f in range(4)}
 markers={p.name: bool(p.exists()) for p in sorted((OUT/'completion').glob('e2e_*'))}
 phase50_processes=live_phase50_workers()
 decision={
  'phase':50,
  'decision_code':'P50_GATE_R_FAIL_END_TO_END_ROUTE_STOP_BEFORE_CONTROLLER',
  'gate_p50':{'status':'PASS','proposal_prefix16_true_iou_ceiling':41,'phase26_candidate_pool_oracle':56,'mot_invariants':'PASS/frozen Phase26 physical rows','source_target_coverage':'inherited Phase26; no semantic mutation'},
  'gate_r50':{'status':retrieval['decision']['gate_r50'],'raw_p16':{'r1':p16['raw']['r1'],'map':p16['raw']['map'],'hard_gap':p16['raw']['hard_gap']},'learned_p16':{'r1':p16['learned']['r1'],'map':p16['learned']['map'],'hard_gap':p16['learned']['hard_gap'],'unsafe_flip_rate':p16['learned']['unsafe_flip_rate']},'r1_delta':retrieval['decision']['r1_margin'],'map_delta':retrieval['decision']['map_margin'],'same_direction_folds':retrieval['decision']['same_direction_folds'],'hard_gap_non_worse':retrieval['decision']['hard_gap_non_worse'],'unsafe_flip_zero':retrieval['decision']['unsafe_flip_zero'],'thresholds':{'r1':0.02,'map':0.01,'folds':3}},
  'gate_c50':{'status':'NOT_RUN','reason':'Gate R50 failed; no controller/Commit-CT execution authorized'},
  'gate_s50':{'status':'NOT_RUN','reason':'Gate C50 not passed; public/sealed labels remain sealed'},
  'fold_p16':folds,
  'training':{'curriculum':['3A frozen Phase26 proposal/physical warm start','3B causal 768-D track encoder','3C support correspondence + semantic state','3D bounded joint semantic/state optimization over frozen physical stream'],'smoke':'e2e_smoke_smoke_f0 and e2e_contract_fix1_smoke_f0 PASS','targeted':'e2e_targeted_f0 500 steps PASS','formal_steps':1000,'formal_folds':[0,1,2,3],'checkpoints':ck,'completion_markers':markers,'physical_stream':'frozen Phase26 passthrough; proposal/MOT losses recorded as zero rather than fabricated GT labels'},
  'resources':{'preflight':resources,'formal_postlaunch_free':str(OUT/'logs/e2e_formal_postlaunch_free.txt'),'formal_postlaunch_gpu':str(OUT/'logs/e2e_formal_postlaunch_gpu.txt'),'estimated_peak_worker_rss_gib':'<2 (feature arrays shared/read-only, one worker per GPU)','ram_safety_floor':'25% available memory maintained','processes_after':phase50_processes or 'none'},
  'data_boundary':{'train_only':True,'positive_event_denominator':76,'prefixes':[1,2,4,8,16],'devplus_q1_public_labels_read':False,'sealed_evaluation_run':False,'future_or_id_inputs':False,'old_phase_files_modified':False},
  'artifacts':{'github_methods':'outputs/iclr27_phase50/audit/github_methods.json','architecture_contract':'outputs/iclr27_phase50/audit/architecture_contract.json','supervision_inventory':'outputs/iclr27_phase50/audit/supervision_inventory.json','leakage_audit':'outputs/iclr27_phase50/audit/leakage_audit.json','retrieval':'outputs/iclr27_phase50/metrics/phase50_retrieval.json'},
  'next_step':'Do not tune gate/controller or download a backbone under the current authorization. A future route requires a separately approved support/task-definition change or richer causal proposal/tracking supervision.'
 }
 OUT.joinpath('audit/phase50_decision.json').write_text(json.dumps(decision,indent=2,sort_keys=True)+'\n')
 curriculum={'phase':50,'stages':{'3A':{'status':'PASS','proposal':'Phase26 frozen','physical_invariants':{'continuity':1.0,'duplicate_physical_tracks':0,'fragmentation_delta':0,'parent_assignment_mismatch':0}},'3B':{'status':'COMPLETE','output_dim':768,'raw_anchor':True},'3C':{'status':'COMPLETE','losses':['multi_positive','hard_negative','prefix_consistency','state_persistence','commit_defer']},'3D':{'status':'COMPLETE','formal_steps':1000,'proposal_and_mot_modules':'frozen passthrough'}}}
 OUT.joinpath('audit/phase50_curriculum.json').write_text(json.dumps(curriculum,indent=2,sort_keys=True)+'\n')
 # Integrity artifact is intentionally lightweight; JSON parse and marker/hash
 # checks are sufficient for this small prototype.
 integrity={'phase':50,'json_parse_check':True,'checkpoints_exist':all(Path(v['path']).exists() for v in ck.values()),'checkpoint_hashes':ck,'symlinks':{'fold_manifest':{'path':str(OUT/'manifests/fold_manifest.json'),'target':str((OUT/'manifests/fold_manifest.json').resolve()),'valid':(OUT/'manifests/fold_manifest.json').is_symlink() and (OUT/'manifests/fold_manifest.json').resolve().exists()}},'completion_markers_exist':all(markers.values()),'phase50_processes':phase50_processes or 'none','public_or_q1_outputs_found':[],'old_phase_outputs_modified':False}
 OUT.joinpath('audit/integrity.json').write_text(json.dumps(integrity,indent=2,sort_keys=True)+'\n')
 report=['# Phase50 — End-to-End MOT+OCD Training Report','','**Execution date:** 2026-08-29  **Decision:** `P50_GATE_R_FAIL_END_TO_END_ROUTE_STOP_BEFORE_CONTROLLER`','','This report records one registered TrackOCD-native end-to-end architecture route. The route was trained only on public TRAIN-derived supervision and stopped before the unchanged controller because its retrieval Gate R50 failed. No retrieval proxy is presented as persistent Commit-CT, and no DEV+, Q1, public new-model or sealed labels were read.','', '## Frozen evidence from Phase24–49','', '- Phase26 proposal/physical MOT: prefix16 true-IoU ceiling **41/76** (candidate-pool diagnostic ceiling 56/76); raw DINOv2 retrieval at p16 is R@1 **0.9000**, mAP **0.8599**.','- Phase46 calibrated gate retrieval passed its registered retrieval screen but unchanged-controller replay produced only **3/76** Commit-CT, confined to fold3; safety/coverage were not broad.','- Phase48 support-conditioned 256-D route fell to R@1/mAP **0.7775/0.7753**. Phase49 raw-preserving 768-D residual reached **0.9117/0.8643** but missed margins and had unsafe flips in all folds.','- These numbers motivate a unified graph, but do not establish complete MOT+OCD success.','','## Official method audit','', 'The official audit is [`GITHUB_METHOD_AUDIT.md`](PHASE50_GITHUB_METHOD_AUDIT.md) and machine-readable [`github_methods.json`](../../outputs/iclr27_phase50/audit/github_methods.json). OVTR (ICLR 2025) supplies an end-to-end open-vocabulary MOT/query template but requires CLIP text embeddings and has no cross-video semantic state; ObjectRelator (ICCV 2025) and C3Po (NeurIPS 2025) address cross-view correspondence but are not causal MOT and/or use incompatible modalities; MOTIP-2, MeMOTR and MOTR are physical-ID/query references; MASA is an external-detector association adapter. No audited method satisfies the complete no-text/no-ID/no-future TrackOCD contract, so none was downloaded or claimed as a solution.','','## Architecture and causal contract','', 'The registered graph is:', '', '```text','video → class-agnostic proposal/objectness → differentiable physical association','      → persistent physical track query → causal track encoder','      → raw-preserving 768-D semantic state → prior-support memory','      → cross-track/cross-video correspondence → semantic StateMemory','      → Commit/Defer controller → persistent Commit-CT','```','', 'The complete contract is [`PHASE50_END_TO_END_ARCHITECTURE_CONTRACT.md`](PHASE50_END_TO_END_ARCHITECTURE_CONTRACT.md) and [`architecture_contract.json`](../../outputs/iclr27_phase50/audit/architecture_contract.json). Physical proposal/association rows came from frozen Phase26 and semantic outputs cannot mutate physical IDs. The model-facing path uses only causal visual vectors, geometry/history, support quality and temporal metadata. Missing support has exact raw fallback. State fields are evidence, persistence, uncertainty and contradiction history; Commit/Defer is causal. Category/track/video labels are metadata-only TRAIN loss/split supervision.','','## TRAIN supervision and leakage','', f"Four video/category-disjoint manifests were reused read-only through [`fold_manifest.json`](../../outputs/iclr27_phase50/manifests/fold_manifest.json). The 43,423×768 key-aligned feature source and manifest hashes are recorded in [`supervision_inventory.json`](../../outputs/iclr27_phase50/audit/supervision_inventory.json). Fit records per fold were {[x['fit_records'] for x in inv['folds']]}, with aggregate **{inv['aggregate']['fit_records']}** multi-positive episodes, **{inv['aggregate']['cross_video_positive_pairs']}** cross-video positive links and **{inv['aggregate']['hard_negative_records']}** hard-negative records. Prefix coverage was registered for 1/2/4/8/16. The leakage audit reports no forbidden model fields, no future rows, no held-event fit use and no DEV+/Q1/public access: [`leakage_audit.json`](../../outputs/iclr27_phase50/audit/leakage_audit.json).",'', '## Curriculum and execution','', '- **3A physical/proposal warm start:** frozen Phase26 proposal and physical rows; inherited invariants continuity 1.0, zero duplicate physical tracks, zero fragmentation delta and zero parent-assignment mismatch.','- **3B causal representation:** LayerNorm/GRU causal track encoder with a bounded residual over the 768-D latest-frame anchor.','- **3C correspondence/state:** causal support memory, multi-positive and hard-negative ranking, prefix consistency, state-persistence and Commit/Defer utility losses.','- **3D joint semantic/state optimization:** one model exposes proposal quality, association, representation, correspondence and state/controller outputs. Proposal/MOT modules remained frozen passthrough in this feature-only run; their losses are recorded as zero rather than fabricated GT detector supervision. This is an honest bounded end-to-end prototype, not a new detector pretraining claim.','', '- Contract smoke (including exact no/invalid-support raw fallback) passed.','- Fold0 targeted 500 steps passed. Four formal 1,000-step folds completed on GPUs 4, 5, 6, 7 with atomic checkpoints and `.launched/.done` markers. No OOM, duplicate supervisor or external process event occurred.','','## Gate R50 retrieval (TRAIN-disjoint diagnostic)','', '| fold | raw R@1 | learned R@1 | raw mAP | learned mAP | raw hard-gap | learned hard-gap | unsafe flip |','|---:|---:|---:|---:|---:|---:|---:|---:|']
 for f in folds:
  x=f['prefix']['16']; report.append(f"| {f['fold']} | {x['raw']['r1']:.4f} | {x['learned']['r1']:.4f} | {x['raw']['map']:.4f} | {x['learned']['map']:.4f} | {x['raw']['hard_gap']:.4f} | {x['learned']['hard_gap']:.4f} | {x['learned']['unsafe_flip_rate']:.4f} |")
 report += [f"| **aggregate** | **{p16['raw']['r1']:.4f}** | **{p16['learned']['r1']:.4f}** | **{p16['raw']['map']:.4f}** | **{p16['learned']['map']:.4f}** | **{p16['raw']['hard_gap']:.4f}** | **{p16['learned']['hard_gap']:.4f}** | **{p16['learned']['unsafe_flip_rate']:.4f}** |",'', 'The full prefix curves and query/support counts are in [`phase50_retrieval.json`](../../outputs/iclr27_phase50/metrics/phase50_retrieval.json). Learned p16 R@1 **decreased by 0.1133**, mAP **decreased by 0.0726**, hard-negative gap collapsed from **0.1944** to **0.0203**, and unsafe flips were **0.1246**. Only fold0 has a small R@1 gain; folds1–3 decline. Thus the registered +0.02 R@1, +0.01 mAP, ≥3-fold, non-worse hard-gap and zero-unsafe criteria fail. The drop is evidence that this particular joint semantic/support optimization is not cross-fold stable, not evidence that DINOv2 has no signal. Training loss reduction cannot be used as task success.','','## Gate decisions','', '| gate | status | evidence |','|---|---|---|','| Gate P50 proposal/physical | PASS (frozen warm start) | Phase26 41/76 source proposal, physical invariants unchanged |','| Gate R50 correspondence | **FAIL** | learned retrieval below raw and safety margins; see table |','| Gate C50 unchanged controller | NOT RUN | prohibited after R50 failure; no Commit-CT claim |','| Gate S50 sealed | NOT RUN | C50 prerequisite failed; sealed/public labels remain sealed |','', 'Because Gate R50 failed, Phase19R controller/StateMemory, thresholds, physical tracker and evaluator were not modified or executed for Phase50. No public or sealed evaluation was launched. This route is complete under its pre-registered single-architecture/one-formal-candidate rule; another model, threshold sweep or backbone download would be an unregistered lottery.','','## Resources, reproducibility and integrity','', f"Preflight: [`resource_preflight.json`](../../outputs/iclr27_phase50/audit/resource_preflight.json). RAM was 125 GiB total with about 119 GiB available; GPUs 4–7 were idle and each formal worker used one card; `/data1` had about 129 GiB free. The post-launch snapshot retained >25% available RAM and no OOM/swap event. There is no usable Git worktree in this project checkout, so artifact hashes are the revision record. Checkpoint SHA256 and completion markers are in [`phase50_decision.json`](../../outputs/iclr27_phase50/audit/phase50_decision.json) and [`integrity.json`](../../outputs/iclr27_phase50/audit/integrity.json). The fold-manifest symlink resolves to the frozen Phase27 TRAIN split; no feature or checkpoint copies were made.",'', 'Reproduction:', '', '```bash','PYTHONPATH=. /home/lwr/anaconda3/envs/locatemot/bin/python scripts/iclr27_phase50/run_phase50_audit.py','PYTHONPATH=. /home/lwr/anaconda3/envs/locatemot/bin/python scripts/iclr27_phase50/contract_smoke.py','CUDA_VISIBLE_DEVICES=4 PYTHONPATH=. /home/lwr/anaconda3/envs/locatemot/bin/python scripts/iclr27_phase50/train_end_to_end.py --fold 0 --smoke --tag e2e_contract_fix1 --device cuda:0 --expected-physical-gpu 4','CUDA_VISIBLE_DEVICES=4 PYTHONPATH=. /home/lwr/anaconda3/envs/locatemot/bin/python scripts/iclr27_phase50/train_end_to_end.py --fold 0 --steps 500 --tag e2e_targeted --device cuda:0 --expected-physical-gpu 4','bash scripts/iclr27_phase50/run_four_fold_supervisor.sh e2e_formal 1000','PYTHONPATH=. CUDA_VISIBLE_DEVICES=4 /home/lwr/anaconda3/envs/locatemot/bin/python scripts/iclr27_phase50/evaluate_retrieval.py --checkpoint-pattern e2e_formal_f{fold}_best.pt --device cuda:0','', 'No controller or sealed command is included because Gate R50 failed. All required Phase50 JSON parsed, checkpoints and markers exist, the symlink is valid, and no Phase50 process remained at finalization.','','## First actionable root cause and next direction','', 'The first actionable Phase50 failure is representation/support optimization: the unified semantic/state residual moved the 768-D anchor toward support-conditioned directions that do not generalize across folds (hard-gap collapse and unsafe flips), while the frozen physical proposal stream was not altered. This is distinct from the historical proposal ceiling and from the earlier frozen-controller interface failures. Under the current authorization, do not tune this controller, add a second encoder, sweep thresholds or download a backbone. A future ICLR route needs an explicitly approved change to causal support/supervision/task definition (or richer end-to-end detector/track supervision) and must re-establish a broad correspondence gate before any persistent Commit-CT or sealed run.','','See [`phase50_decision.json`](../../outputs/iclr27_phase50/audit/phase50_decision.json) for the machine-readable decision.']
 (DOC/'PHASE50_END_TO_END_TRAINING_REPORT.md').write_text('\n'.join(report)+'\n',encoding='utf-8')
 print(json.dumps({'decision':decision['decision_code'],'gate_r50':decision['gate_r50']['status'],'report':str(DOC/'PHASE50_END_TO_END_TRAINING_REPORT.md')},indent=2))

if __name__=='__main__': main()
